#include &lt;numeric&gt;  // for std::gcd
using namespace std;

int main() {
    int num = 18;
    int den = 24;

    int common = std::gcd(num, den);

    num /= common;
    den /= common;

    cout &lt;&lt; num &lt;&lt; "/" &lt;&lt; den;  // Outputs: 3/4
