السطر sort(arr.begin(), arr.end()); يرتب الـ vector بأكمله تصاعديًا.



يمكنك أيضًا استخدام نفس sort مع المصفوفات العادية:

#include &lt;iostream&gt;
#include &lt;algorithm&gt;
using namespace std;

int main() {
    int n = 5;

    int arr[] = {5, 8, 3, 4, 2};

    sort(arr, arr + n);

    for (int i = 0; i &lt; n; i++)
        cout &lt;&lt; arr[i] &lt;&lt; ' ';
    cout &lt;&lt; '\n';
}

