#include &lt;iostream&gt;
#include &lt;map&gt;
#include &lt;string&gt;
using namespace std;

int main() {
    string text = "apple banana apple orange banana apple";
    map&lt;string, int&gt; freq;

    string word;
    for (auto c : text) {
        if (c == ' ') {
            if (!word.empty()) freq[word]++;
            word.clear();
        } else {
            word += c;
        }
    }
    if (!word.empty()) freq[word]++;  // آخر كلمة

    for (auto p : freq)
        cout &lt;&lt; p.first &lt;&lt; ": " &lt;&lt; p.second &lt;&lt; endl;
}

الناتج:

apple: 3
banana: 2
orange: 1




