الحل



#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;algorithm&gt;
using namespace std;

int main() {
    int n; cin &gt;&gt; n;
    vector&lt;int&gt; strength(n);
    for (int &x : strength) cin &gt;&gt; x;

    int seconds = 0;
    while (true) {
        sort(strength.begin(), strength.end());
