#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

int main() {
    int n;
    cin &gt;&gt; n;
    int x = 0;

    while (n--) {
        string s;
        cin &gt;&gt; s;               // s هي واحدة من: ++X, X++, --X, X--
        if (s[1] == '+') {
            ++x;   // الحرف الأوسط يحدد العملية
        } else {
            --x;
        }
    }

    cout &lt;&lt; x;
}








