int main() {
    int a = 6;   // 00000110
    int b = 10;  // 00001010

    cout &lt;&lt; "a = "; printBits(a); cout &lt;&lt; " (" &lt;&lt; a &lt;&lt; ")\n";
    cout &lt;&lt; "b = "; printBits(b); cout &lt;&lt; " (" &lt;&lt; b &lt;&lt; ")\n\n";

    cout &lt;&lt; "a & b = "; printBits(a & b); cout &lt;&lt; " (" &lt;&lt; (a & b) &lt;&lt; ")\n";
    cout &lt;&lt; "a | b = "; printBits(a | b); cout &lt;&lt; " (" &lt;&lt; (a | b) &lt;&lt; ")\n";
    cout &lt;&lt; "a ^ b = "; printBits(a ^ b); cout &lt;&lt; " (" &lt;&lt; (a ^ b) &lt;&lt; ")\n";
    cout &lt;&lt; "~a    = "; printBits((unsigned char)~a); cout &lt;&lt; " (only low 8 bits)\n";

    cout &lt;&lt; "a &lt;&lt; 1 = "; printBits(a &lt;&lt; 1); cout &lt;&lt; " (" &lt;&lt; (a &lt;&lt; 1) &lt;&lt; ")\n";
