لديك ثلاث مصفوفات \(a\)، \(b\)، و \(c\) من الأعداد الصحيحة، كل منها بطول \(N\). في كل موقع \(i\) (حيث \(0 \le i &lt; N\)) يجب اختيار عنصر من \(a_i\)، \(b_i\)، أو \(c_i\).
شرط: لكل موقع \(i\) (حيث \(0 \le i &lt; N - 1\))، يجب أن تأتي العناصر المختارة عند المواقع \(i\) و \(i + 1\) من مصفوفات مختلفة.
حدد واطبع أكبر مجموع للعناصر المختارة يمكن تحقيقه تحت هذا الشرط.









ملاحظةملحوظة



لتبسيط المشكلة، سنمثل المصفوفات الثلاث \(a\)، \(b\)، و \(c\) كمصفوفة ثنائية الأبعاد واحدة \(d\) بأبعاد \(N \times 3\).
البعد الأول طوله \(N\)، والبُعد الثاني طوله \(3\)، حيث \(d_i\) هو مصفوفة تحتوي القيم [\(a_i\), \(b_i\), \(c_i\)].



الحل

سنحل هذه المشكلة باستخدام البرمجة الديناميكية.
دعنا نعرف الحالة:
\(f(i, type)\) هو أكبر مجموع ممكن إذا اعتبرنا أول \(i\) عنصر وعند الموقع \(i\) اخترنا \(d[i][type]\).
بعد ذلك نعرف الانتقال. هناك ثلاث انتقالات مختلفة بناءً على \(type\):
 \(f(i , 0) = max(f(i - 1, 1) , f(i - 1, 2)) + d_{i,0}\)
\(f(i , 1) = max(f(i - 1, 0) , f(i - 1, 2)) + d_{i,1}\)
\(f(i , 2) = max(f(i - 1, 0) , f(i - 1, 1)) + d_{i,2}\)

الحالة الأساسية:
\(f(0, type) = d_{0,type}\)
تعقيد المساحة يحدده عدد الحالات، وهو \(O(N)\).
التعقيد الزمني هو عدد الحالات \(N\) مضروبًا في تعقيد كل انتقال \(O(1)\)، لذا التعقيد الكلي هو \(O(N)\).

#include &lt;iostream&gt;
using namespace std;

int dp[200000][3];
int d[200000][3];


int f(int i, int type) {

    if (i == 0) {
        return d[i][type];
    }

    if (dp[i][type] != -1) {
        return dp[i][type];
    }

    if (type == 0) {
        dp[i][type] = max(f(i - 1, 1), f(i - 1, 2)) + d[i][type];
    } else if (type == 1) {
        dp[i][type] = max(f(i - 1, 0), f(i - 1, 2)) + d[i][type];
    } else if (type == 2) {
        dp[i][type] = max(f(i - 1, 0), f(i - 1, 1)) + d[i][type];
    }

    return dp[i][type];
}


int main() {

    for (int i = 0; i &lt; 200000; i++) {
        for (int j = 0; j &lt; 3; j++) {
            dp[i][j] = -1;
        }
    }

    int n;
    cin &gt;&gt; n;

    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; 3; j++) {
            cin &gt;&gt; d[i][j];
        }
    }

    cout &lt;&lt; max(max(f(n - 1, 0), f(n - 1, 1)), f(n - 1, 2)) &lt;&lt; "\n";
}

تختص هندسة المستطيلات بالمستطيلات التي تكون أضلاعها موازية لمحوري الإحداثيات. يشرح هذا القسم العمليات الأساسية المستخدمة مع هذه المستطيلات.






ملاحظة



نفترض أن الاتجاه الموجب للمحور \(X\) يشير إلى اليمين، وأن الاتجاه الموجب للمحور \(Y\) يشير إلى الأعلى.




تحتوي النقطة على إحداثيين: إحداثي \(x\) وإحداثي \(y\). يمكننا جمعهما في بنية واحدة:

struct Point {
    int x;
    int y;
};

يمكن تمثيل المستطيل الموازي للمحورين بنقطتي الزاوية السفلية اليسرى والزاوية العلوية اليمنى. نجمع هاتين النقطتين في بنية أخرى:

struct Rectangle {
    Point bottom_left;
    Point top_right;
};

نفترض في هذا القسم أن إحداثيات كل مستطيل مرتبة كما يلي:

bottom_left.x &lt;= top_right.x
bottom_left.y &lt;= top_right.y






العرض هو المسافة الأفقية بين ضلعي المستطيل:
width = r.top_right.x - r.bottom_left.x
الارتفاع هو المسافة العمودية بين ضلعي المستطيل:
height = r.top_right.y - r.bottom_left.y
المساحة هي حاصل ضرب العرض في الارتفاع:
area = width * height

int area(Rectangle r) {
    int width = r.top_right.x - r.bottom_left.x;
    int height = r.top_right.y - r.bottom_left.y;
    return width * height;
}




يتقاطع مستطيلان بمساحة موجبة فقط إذا تداخل مجالاهما على المحور \(X\) وعلى المحور \(Y\). غالبًا ما يكون التحقق من الحالة العكسية أسهل.
يكون المستطيلان منفصلين أفقيًا إذا انتهى أحدهما عند بداية الآخر أو قبلها. وينطبق الشرط نفسه عموديًا باستخدام إحداثيات المحور \(Y\). إذا تحقق أي من شرطي الانفصال، فلا يتقاطع المستطيلان.

bool rectangles_intersect(Rectangle a, Rectangle b) {
    bool separated_x = a.top_right.x &lt;= b.bottom_left.x ||
        b.top_right.x &lt;= a.bottom_left.x;
    bool separated_y = a.top_right.y &lt;= b.bottom_left.y ||
        b.top_right.y &lt;= a.bottom_left.y;

    return !separated_x && !separated_y;
}







ملاحظة



إذا تلامس المستطيلان عند ضلع أو زاوية فقط، فإن مساحة الجزء المشترك تساوي صفرًا؛ لذلك لا نعدهما متقاطعين.





إذا تقاطع المستطيلان a وb، فإن تقاطعهما يكون مستطيلًا آخر. نأخذ لكل إحداثي في النقطة السفلية اليسرى القيمة الكبرى، ولكل إحداثي في النقطة العلوية اليمنى القيمة الصغرى.

#include &lt;algorithm&gt;
using namespace std;

Rectangle rectangle_intersection(Rectangle a, Rectangle b) {
    Rectangle c;
    c.bottom_left.x = max(a.bottom_left.x, b.bottom_left.x);
    c.bottom_left.y = max(a.bottom_left.y, b.bottom_left.y);
    c.top_right.x = min(a.top_right.x, b.top_right.x);
    c.top_right.y = min(a.top_right.y, b.top_right.y);
    return c;
}

لا نستدعي الدالة rectangle_intersection إلا بعد أن تؤكد الدالة rectangles_intersect وجود تقاطع.




تنطبق الأفكار نفسها في بعد واحد، حيث نتعامل مع الفترات بدلًا من المستطيلات. تحتوي الفترة على طرف أيسر وطرف أيمن:

struct Interval {
    int left;
    int right;
};

نفترض أن طرفي كل فترة مرتبان، أي إن left &lt;= right.


يُحسب طول الفترة كما يلي:
length = segment.right - segment.left

int length(Interval segment) {
    return segment.right - segment.left;
}




تتقاطع فترتان بطول موجب ما لم تنتهِ إحداهما عند بداية الأخرى أو قبلها:

bool intervals_intersect(Interval a, Interval b) {
    return a.right &gt; b.left && b.right &gt; a.left;
}

كما في المستطيلات، إذا اشتركت الفترتان في طرف واحد فقط، فإن طول التقاطع يساوي صفرًا ولا نعدهما متقاطعتين.



إذا تقاطعت الفترتان a وb، فإن فترة التقاطع تبدأ عند الطرف الأيسر الأكبر وتنتهي عند الطرف الأيمن الأصغر:

#include &lt;algorithm&gt;
using namespace std;

Interval interval_intersection(Interval a, Interval b) {
    Interval c;
    c.left = max(a.left, b.left);
    c.right = min(a.right, b.right);
    return c;
}










