لدينا فترتان، والمطلوب طباعة الطول الإجمالي الذي تغطيانه.




الحل

نجمع طولي الفترتين، ثم نطرح طول الجزء الذي تغطيانه معًا. إذا لم تتداخل الفترتان، يكون طول الجزء المشترك صفرًا.

#include &lt;algorithm&gt;
#include &lt;cstdio&gt;
#include &lt;iostream&gt;
using namespace std;

struct Interval {
    int left;
    int right;
};

int length(Interval segment) {
    return segment.right - segment.left;
}

int overlap_length(Interval a, Interval b) {
    int left = max(a.left, b.left);
    int right = min(a.right, b.right);
    return max(0, right - left);
}

int main() {
    freopen("paint.in", "r", stdin);
    freopen("paint.out", "w", stdout);

    Interval a, b;
    cin &gt;&gt; a.left &gt;&gt; a.right &gt;&gt; b.left &gt;&gt; b.right;

    int total = length(a) + length(b) - overlap_length(a, b);
    cout &lt;&lt; total &lt;&lt; "\n";
}

